        this.sheetId = sheetId;
        this.userName = userName;
        this.role = role;
        this.setOn = setOn;
    }

    public String getUserName() {
        return userName;
    }

    public String getRole() {
        return role;
    }

    public LocalDate getSetOn() {
        return setOn;
